<!DOCTYPE html>
<html lang="vi">
<head>
    <meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><title>Fieldcraft Admin</title>
    <link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link href="https://fonts.googleapis.com/css2?family=DM+Mono:wght@400;500&family=Manrope:wght@400;500;600;700;800&family=Oswald:wght@500;600;700&display=swap" rel="stylesheet">
    <style>
        :root{--ink:#07110d;--soft:#eff3ec;--lime:#caff39;--muted:#718078;--line:#e2e8e0;--red:#ff5c35}*{box-sizing:border-box}body{margin:0;color:var(--ink);font:500 13px Manrope,sans-serif;background:#f7f9f5}.side{position:fixed;inset:0 auto 0 0;width:250px;background:var(--ink);color:white;padding:26px 16px;display:flex;flex-direction:column}.brand{font:700 24px/1 Oswald,sans-serif;margin:5px 9px 45px}.brand i{display:inline-block;width:18px;height:18px;margin-right:7px;background:var(--lime);border-radius:2px 10px 2px 10px;transform:rotate(-20deg)}.role{font:500 9px 'DM Mono';letter-spacing:.14em;color:#8b9b8f;margin:0 10px 10px}.nav a{display:flex;gap:12px;align-items:center;padding:11px 10px;margin:2px 0;border-radius:5px;color:#b8c5ba;text-decoration:none;font-size:12px;font-weight:700}.nav a.active,.nav a:hover{background:#23382c;color:white}.nav a.active span{color:var(--lime)}.user{margin-top:auto;padding:13px 10px;border-top:1px solid #273a2f;display:flex;gap:9px;align-items:center}.avatar{width:31px;height:31px;border-radius:50%;background:var(--lime);color:var(--ink);display:grid;place-items:center;font-weight:800}.user small{display:block;color:#8d9d90;font-size:9px}.user b{font-size:11px}.main{margin-left:250px;padding:34px 40px}.crumb{font:500 10px 'DM Mono';color:var(--muted);letter-spacing:.1em}.header{display:flex;justify-content:space-between;align-items:flex-end;margin:10px 0 30px}.header h1{font:600 40px/.95 Oswald,sans-serif;text-transform:uppercase;margin:8px 0}.date{border:1px solid var(--line);background:white;border-radius:4px;padding:10px 14px;font-size:11px}.stats{display:grid;grid-template-columns:repeat(4,1fr);gap:14px}.stat{background:white;padding:18px;border:1px solid var(--line);border-radius:7px}.stat small{font-size:10px;color:var(--muted)}.stat h2{font:600 27px/1 Oswald,sans-serif;margin:8px 0}.trend{font:500 10px 'DM Mono';color:#438a32}.trend.down{color:var(--red)}.grid{display:grid;grid-template-columns:1.55fr .9fr;gap:16px;margin-top:16px}.panel{background:white;border:1px solid var(--line);border-radius:8px;padding:20px}.panel-head{display:flex;align-items:center;justify-content:space-between;margin-bottom:18px}.panel h3{font-size:13px;margin:0}.panel p{font-size:10px;color:var(--muted);margin:3px 0}.select{border:1px solid var(--line);padding:6px 9px;background:white;border-radius:3px;font-size:10px}.chart{height:250px;position:relative;background:repeating-linear-gradient(0deg,transparent 0,transparent 48px,#edf1ea 49px)}.chart svg{position:absolute;inset:0;width:100%;height:100%;overflow:visible}.chart-labels{display:flex;justify-content:space-between;margin-top:8px;color:var(--muted);font:9px 'DM Mono'}.orders{margin-top:16px}.table{width:100%;border-collapse:collapse}.table th{text-align:left;color:var(--muted);font:500 9px 'DM Mono';letter-spacing:.08em;padding:7px 10px;border-bottom:1px solid var(--line)}.table td{padding:12px 10px;border-bottom:1px solid #f0f3ef;font-size:11px}.status{display:inline-block;padding:4px 6px;border-radius:2px;font:500 9px 'DM Mono'}.yellow{background:#fff5ce;color:#967000}.blue{background:#e6f0ff;color:#2c69ba}.green{background:#e5f6db;color:#40802c}.rank{display:flex;gap:10px;align-items:center;margin:14px 0}.rank-img{width:38px;height:38px;object-fit:cover;background:var(--soft);border-radius:4px}.rank b{display:block;font-size:11px}.rank small{color:var(--muted);font-size:9px}.bar{height:4px;background:#edf1eb;border-radius:2px;margin-top:5px;width:150px}.bar i{display:block;height:100%;background:var(--lime);border-radius:2px}@media(max-width:900px){.side{width:62px;padding:20px 9px}.brand{font-size:0;margin:7px 14px 45px}.brand i{width:24px;height:24px;margin:0}.role,.nav a b,.user div{display:none}.nav a{justify-content:center;padding:12px}.main{margin-left:62px;padding:25px 18px}.stats{grid-template-columns:repeat(2,1fr)}.grid{grid-template-columns:1fr}.header h1{font-size:34px}}@media(max-width:520px){.main{padding:18px 12px}.stats{gap:8px}.stat{padding:13px}.stat h2{font-size:22px}.table th:nth-child(3),.table td:nth-child(3){display:none}.date{display:none}}
    </style>
</head>
<body>
    <aside class="side"><a class="brand" href="{{ route('store.home') }}"><i></i>FIELDCRAFT</a><div class="role">CONTROL ROOM</div><nav class="nav"><a class="active" href="#"><span>▦</span><b>Tổng quan</b></a><a href="#orders"><span>□</span><b>Đơn hàng <em style="background:#caff39;color:#07110d;padding:2px 5px;border-radius:8px;font-style:normal;font-size:9px">12</em></b></a><a href="#"><span>◇</span><b>Sản phẩm</b></a><a href="#"><span>◉</span><b>Khách hàng</b></a><a href="#"><span>%</span><b>Mã giảm giá</b></a><a href="#"><span>⌁</span><b>Báo cáo</b></a></nav><div class="user"><div class="avatar">HD</div><div><b>Hải Đăng</b><small>Super admin</small></div></div></aside>
    <main class="main"><div class="crumb">DASHBOARD / OVERVIEW</div><div class="header"><div><h1>Chào buổi sáng, Hải.</h1><span style="color:#718078;font-size:12px">Sân cỏ đang sôi động. Đây là nhịp kinh doanh hôm nay.</span></div><button class="date">◷ &nbsp; 15 — 21 THÁNG 8, 2026</button></div><section class="stats"><article class="stat"><small>DOANH THU TUẦN</small><h2>48.290.000₫</h2><span class="trend">↑ 12.6% so với tuần trước</span></article><article class="stat"><small>ĐƠN HÀNG</small><h2>184</h2><span class="trend">↑ 8.2% so với tuần trước</span></article><article class="stat"><small>KHÁCH MỚI</small><h2>79</h2><span class="trend">↑ 15.4% so với tuần trước</span></article><article class="stat"><small>TỶ LỆ CHUYỂN ĐỔI</small><h2>3.84%</h2><span class="trend down">↓ 0.4% so với tuần trước</span></article></section><section class="grid"><article class="panel"><div class="panel-head"><div><h3>Doanh thu theo ngày</h3><p>Gross merchandise value · VNĐ</p></div><select class="select"><option>7 ngày qua</option><option>30 ngày qua</option></select></div><div class="chart"><svg viewBox="0 0 650 250" preserveAspectRatio="none"><defs><linearGradient id="fill" x1="0" x2="0" y1="0" y2="1"><stop stop-color="#caff39" stop-opacity=".36"/><stop offset="1" stop-color="#caff39" stop-opacity="0"/></linearGradient></defs><path d="M0 205 L65 180 L130 194 L195 137 L260 158 L325 102 L390 124 L455 70 L520 92 L585 38 L650 58 L650 250 L0 250Z" fill="url(#fill)"/><path d="M0 205 L65 180 L130 194 L195 137 L260 158 L325 102 L390 124 L455 70 L520 92 L585 38 L650 58" fill="none" stroke="#1d5735" stroke-width="3"/><circle cx="585" cy="38" r="5" fill="#caff39" stroke="#1d5735" stroke-width="3"/></svg></div><div class="chart-labels"><span>T2</span><span>T3</span><span>T4</span><span>T5</span><span>T6</span><span>T7</span><span>CN</span></div></article><article class="panel"><div class="panel-head"><div><h3>Top sản phẩm</h3><p>Đơn vị bán trong tuần</p></div><button class="select">XEM TẤT CẢ</button></div><div class="rank"><img class="rank-img" src="https://images.unsplash.com/photo-1511886929837-354d827aae26?auto=format&fit=crop&w=100&q=70"><div style="flex:1"><b>Adidas F50 Elite FG</b><small>42 đôi · 205.380.000₫</small><div class="bar"><i style="width:92%"></i></div></div></div><div class="rank"><img class="rank-img" src="https://images.unsplash.com/photo-1552346154-21d32810aba3?auto=format&fit=crop&w=100&q=70"><div style="flex:1"><b>Nike Mercurial Vapor 16</b><small>37 đôi · 158.730.000₫</small><div class="bar"><i style="width:78%"></i></div></div></div><div class="rank"><img class="rank-img" src="https://images.unsplash.com/photo-1579952363873-27d3bfad9c0d?auto=format&fit=crop&w=100&q=70"><div style="flex:1"><b>Áo Messi Inter Miami</b><small>31 chiếc · 58.590.000₫</small><div class="bar"><i style="width:65%"></i></div></div></div><div class="rank"><img class="rank-img" src="https://images.unsplash.com/photo-1575361204480-aadea25e6e68?auto=format&fit=crop&w=100&q=70"><div style="flex:1"><b>Bóng Adidas League</b><small>24 quả · 26.160.000₫</small><div class="bar"><i style="width:50%"></i></div></div></div></article></section><section class="panel orders" id="orders"><div class="panel-head"><div><h3>Đơn hàng gần đây</h3><p>Cần hành động trong hôm nay</p></div><button class="select">MỞ QUẢN LÝ ĐƠN →</button></div><table class="table"><thead><tr><th>MÃ ĐƠN</th><th>KHÁCH HÀNG</th><th>SẢN PHẨM</th><th>THANH TOÁN</th><th>TRẠNG THÁI</th><th>TỔNG</th></tr></thead><tbody><tr><td>#FC-4821</td><td>Nguyễn Minh Anh</td><td>F50 Elite FG × 1</td><td>COD</td><td><span class="status yellow">CHỜ DUYỆT</span></td><td>4.890.000₫</td></tr><tr><td>#FC-4820</td><td>Trần Gia Huy</td><td>Mercurial Vapor × 1</td><td>VNPay</td><td><span class="status blue">ĐANG GIAO</span></td><td>4.290.000₫</td></tr><tr><td>#FC-4819</td><td>Lê Ngọc Bích</td><td>Áo Messi × 2</td><td>VNPay</td><td><span class="status green">HOÀN THÀNH</span></td><td>3.780.000₫</td></tr></tbody></table></section></main>
